from pathlib import Path
import base64
import hashlib
base=Path(__file__).resolve().parent
root=base.parent/'public'
app=(root/'app.js').read_text()
app=app.replace("p.image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(p.file);});", "p.image=await smallImage(p.file);")
app=app.replace("$('#modal').showModal();if(submit)", "$('#modal').showModal();$('dialog form').addEventListener('submit',e=>e.preventDefault());if(submit)")
adapter=r'''
const storageKey='pkm-standalone-v1';
const blank=()=>({sets:[],cards:[],versions:[],locations:[],holdings:[]});
__STORAGE__
const next=(rows)=>Math.max(0,...rows.map(r=>r.id))+1;
const req=(v,label)=>{if(typeof v!=='string'||!v.trim())throw Error(label+' skal udfyldes');return v.trim();};
window.fetch=async function(url,opts={}){try{
const d=stored();if(url==='/api/state')return new Response(JSON.stringify(d));
const p=JSON.parse(opts.body),route=url.split('/').pop();const tracked=['adjust','holdings','move','remove','edit-holding','bulk-holdings'];const holdingsBefore=tracked.includes(route)?structuredClone(d.holdings):null;
function card(c){const set_id=Number(c.set_id);if(!d.sets.some(s=>s.id===set_id))throw Error('Vælg et set');const name=req(c.name,'Navn'),number=req(c.number,'Kortnummer');if(d.cards.some(k=>k.set_id===set_id&&k.number===number))throw Error('Kortnummer findes allerede i dette set');const names=[...new Set((c.versions||['Normal']).map(v=>req(v,'Version')))];if(!names.length)throw Error('Tilføj en version');const image=String(c.image||'');if(image&&!/^https?:\/\//.test(image)&&!/^data:image\/(png|jpeg|webp|gif);base64,/.test(image))throw Error('Ugyldigt billede');const id=next(d.cards);d.cards.push({id,set_id,name,number,image,englishName:String(c.englishName||''),japaneseName:String(c.japaneseName||''),nameStatus:c.nameStatus||(!c.englishName?'missing':'source'),versionsStatus:c.versionsStatus||(c.versionsKnown===false?'missing':'source')});for(const name of names){const links=(c.cardmarketLinks||[]).filter(l=>l.version===name);if(links.length>1)throw Error('Flere links til samme version');const v={id:next(d.versions),card_id:id,name};if(links.length)v.cardmarketUrl=cmNormalize(links[0].url,d.sets.find(s=>s.id===set_id).language);d.versions.push(v);}if((c.cardmarketLinks||[]).some(l=>!names.includes(l.version)))throw Error('Link til ukendt version');}
switch(route){
case 'import-sets':{if(!Array.isArray(p.sets)||!p.sets.length)throw Error('Ingen sets');for(const s of p.sets){const name=req(s.name,'Setnavn'),language=String(s.language||'');if(d.sets.some(x=>s.sourceId&&x.sourceId===s.sourceId&&x.language===language||(x.name.toLowerCase()===name.toLowerCase()||x.englishName?.toLowerCase()===name.toLowerCase())&&(!x.language||x.language===language)))throw Error('Set findes allerede: '+name);if(!Array.isArray(s.cards)||!s.cards.length)throw Error('Set har ingen kort');const id=next(d.sets);d.sets.push({id,name,game:String(s.game||'Pokémon'),year:String(s.year||s.releaseDate?.slice(0,4)||''),language,series:String(s.series||'Øvrige sets'),releaseDate:String(s.releaseDate||''),japaneseName:String(s.japaneseName||''),setCode:String(s.setCode||s.sourceId||''),englishName:String(s.englishName||s.name||''),sourceId:String(s.sourceId||''),source:String(s.source||''),officialTotal:Number(s.officialTotal||s.cards.length)});for(const c of s.cards)card({...c,set_id:id});}break;}
case 'adjust':{const version_id=Number(p.version_id),location_id=Number(p.location_id),condition=req(p.condition,'Stand'),delta=Number(p.delta);if(![-1,1].includes(delta)||!d.versions.some(v=>v.id===version_id)||!d.locations.some(l=>l.id===location_id))throw Error('Ugyldig registrering');const hs=d.holdings.filter(h=>h.version_id===version_id&&h.location_id===location_id&&h.condition===condition);const h=hs.at(-1);if(delta===-1){if(!h)throw Error('Ingen eksemplarer på denne lokation i den valgte stand');if(h.quantity===1)d.holdings=d.holdings.filter(r=>r.id!==h.id);else h.quantity--;}else if(h)h.quantity++;else d.holdings.push({id:next(d.holdings),version_id,location_id,condition,quantity:1});break;}
case 'upgrade-names':{for(const change of p.cards||[]){const c=d.cards.find(c=>c.id===change.id);if(c&&c.nameStatus!=='user'){c.name=req(change.name,'Navn');c.englishName=String(change.englishName||'');c.japaneseName=String(change.japaneseName||'');}}for(const change of p.sets||[]){const s=d.sets.find(s=>s.id===change.id);if(s)Object.assign(s,{name:req(change.name,'Setnavn'),englishName:String(change.englishName||''),setCode:String(change.setCode||s.sourceId||'')});}break;}
case 'set-code':{const s=d.sets.find(s=>s.id===Number(p.id)),code=req(p.setCode,'Setkode').toUpperCase();if(!s||!/^[-A-Z0-9.]+$/.test(code))throw Error('Ugyldig setkode');if(d.sets.some(x=>x.id!==s.id&&(x.setCode||x.sourceId||'').toUpperCase()===code))throw Error('Setkoden er allerede i brug');s.setCode=code;break;}
case 'bulk-holdings':{if(!Array.isArray(p.rows)||!p.rows.length)throw Error('Ingen kort valgt');for(const row of p.rows){const version_id=Number(row.version_id),location_id=Number(p.location_id),quantity=Number(row.quantity),condition=req(p.condition,'Stand');if(!d.versions.some(v=>v.id===version_id)||!d.locations.some(l=>l.id===location_id)||!Number.isSafeInteger(quantity)||quantity<1)throw Error('Ugyldig beholdning');const h=d.holdings.find(h=>h.version_id===version_id&&h.location_id===location_id&&h.condition===condition);if(h)h.quantity+=quantity;else d.holdings.push({id:next(d.holdings),version_id,location_id,quantity,condition});}break;}
case 'undo':{const entry=d.undoStack?.at(-1);if(!entry)throw Error('Ingen ændring kan fortrydes');if(!Array.isArray(entry.holdings)||entry.holdings.some(h=>!d.versions.some(v=>v.id===h.version_id)||!d.locations.some(l=>l.id===h.location_id)||!Number.isSafeInteger(h.quantity)||h.quantity<1))throw Error('Fortrydelsesdata er ugyldige');d.holdings=structuredClone(entry.holdings);d.undoStack.pop();d.auditLog=d.auditLog||[];d.auditLog.push({id:next(d.auditLog),time:new Date().toISOString(),action:'undo',description:'Fortrød '+entry.description});break;}
case 'edit-catalog':{const c=d.cards.find(c=>c.id===Number(p.id));if(!c)throw Error('Ukendt kort');const englishName=req(p.englishName,'Engelsk navn'),japaneseName=String(p.japaneseName||'').trim();c.englishName=englishName;c.japaneseName=japaneseName;c.name=englishName+(japaneseName?' ('+japaneseName+')':'');c.nameStatus='user';c.qualityChecked=Boolean(p.qualityChecked);c.qualityCheckedAt=c.qualityChecked?new Date().toISOString():'';break;}
case 'import-bundle':{if(!Array.isArray(p.sets)||!p.sets.length)throw Error('Ingen sets valgt');for(const s of p.sets){const name=req(s.name,'Setnavn'),language=String(s.language||'ja');if(d.sets.some(x=>s.sourceId&&x.sourceId===s.sourceId&&x.language===language||x.name.toLowerCase()===name.toLowerCase()))throw Error('Set findes allerede: '+name);if(!Array.isArray(s.cards)||!s.cards.length)throw Error('Set har ingen kort');const id=next(d.sets);d.sets.push({id,name,englishName:String(s.englishName||name),japaneseName:String(s.japaneseName||''),setCode:String(s.setCode||s.sourceId||''),sourceId:String(s.sourceId||''),source:String(s.source||''),language,series:String(s.series||'Øvrige sets'),game:String(s.game||'Pokémon'),year:String(s.year||s.releaseDate?.slice(0,4)||''),releaseDate:String(s.releaseDate||''),officialTotal:Number(s.officialTotal||s.cards.length)});for(const c of s.cards)card({...c,set_id:id});}break;}
case 'sets':d.sets.push({id:next(d.sets),name:req(p.name,'Setnavn'),game:p.game||'',year:p.year||''});break;
case 'locations':{const name=req(p.name,'Lokation');if(d.locations.some(l=>l.name===name))throw Error('Lokationen findes allerede');d.locations.push({id:next(d.locations),name});break;}
case 'cards':card(p);break;
case 'import':if(!p.cards?.length)throw Error('Ingen kort');p.cards.forEach(card);break;
case 'cardmarket-links':{if(!Array.isArray(p.links)||!p.links.length)throw Error('Ingen Cardmarket-links valgt');const seen=new Set();for(const item of p.links){const v=d.versions.find(v=>v.id===Number(item.version_id));if(!v)throw Error('Ukendt kortversion');if(seen.has(v.id))throw Error('Flere links til samme version');seen.add(v.id);const raw=String(item.url||'').trim();if(!raw){if(!p.allowClear)throw Error('Cardmarket-link mangler');delete v.cardmarketUrl;continue;}let u;try{u=new URL(raw);}catch{throw Error('Ugyldig Cardmarket-adresse');}if(raw.length>2048||u.protocol!=='https:'||!['www.cardmarket.com','cardmarket.com'].includes(u.hostname)||u.username||u.password||u.port||!/^\/[a-z]{2}\/Pokemon\/Products\/Singles\/[^/]+\/[^/]+\/?$/.test(u.pathname))throw Error('Brug et HTTPS-link til en Cardmarket Pokémon-produktside');u.hostname='www.cardmarket.com';u.hash='';const c=d.cards.find(c=>c.id===v.card_id),s=d.sets.find(s=>s.id===c.set_id);if(s.language==='ja'&&!u.searchParams.has('language'))u.searchParams.set('language','7');v.cardmarketUrl=u.href;}break;}
case 'versions':{const card_id=Number(p.card_id),name=req(p.name,'Version');if(!d.cards.some(c=>c.id===card_id))throw Error('Ukendt kort');if(d.versions.some(v=>v.card_id===card_id&&v.name===name))throw Error('Versionen findes allerede');d.versions.push({id:next(d.versions),card_id,name});break;}
case 'holdings':{const version_id=Number(p.version_id),location_id=Number(p.location_id),quantity=Number(p.quantity);if(!d.versions.some(v=>v.id===version_id)||!d.locations.some(l=>l.id===location_id))throw Error('Vælg version og lokation');if(!Number.isSafeInteger(quantity)||quantity<1)throw Error('Antal skal være et positivt heltal');d.holdings.push({id:next(d.holdings),version_id,location_id,quantity,condition:req(p.condition,'Stand')});break;}
case 'wishlist':{const c=d.cards.find(c=>c.id===Number(p.id));if(!c)throw Error('Ukendt kort');c.wishlist=!c.wishlist;break;}
case 'edit-card':{const c=d.cards.find(c=>c.id===Number(p.id));if(!c)throw Error('Ukendt kort');const name=req(p.name,'Navn'),number=req(p.number,'Kortnummer'),set_id=Number(p.set_id),image=String(p.image||'');if(!d.sets.some(s=>s.id===set_id))throw Error('Vælg et set');if(d.cards.some(k=>k.id!==c.id&&k.set_id===set_id&&k.number===number))throw Error('Kortnummer findes allerede');if(image&&!/^https?:\/\//.test(image)&&!/^data:image\/(png|jpeg|webp|gif);base64,/.test(image))throw Error('Ugyldigt billede');Object.assign(c,{name,number,set_id,image});break;}
case 'edit-holding':{const h=d.holdings.find(h=>h.id===Number(p.id)),quantity=Number(p.quantity),location_id=Number(p.location_id);if(!h||!d.locations.some(l=>l.id===location_id))throw Error('Ukendt beholdning eller lokation');if(!Number.isSafeInteger(quantity)||quantity<1)throw Error('Antal skal være et positivt heltal');Object.assign(h,{quantity,location_id,condition:req(p.condition,'Stand')});break;}
case 'images':{if(!Array.isArray(p.images)||!p.images.length)throw Error('Ingen billeder');for(const im of p.images){const c=d.cards.find(c=>c.id===Number(im.id));if(!c||!/^data:image\/(png|jpeg|webp|gif);base64,/.test(im.image))throw Error('Ugyldigt billede');c.image=im.image;}break;}
case 'move':{const h=d.holdings.find(h=>h.id===Number(p.id));if(!h||!d.locations.some(l=>l.id===Number(p.location_id)))throw Error('Ukendt beholdning eller lokation');h.location_id=Number(p.location_id);break;}
case 'remove':d.holdings=d.holdings.filter(h=>h.id!==Number(p.id));break;
default:throw Error('Ukendt handling');}
if(holdingsBefore&&JSON.stringify(holdingsBefore)!==JSON.stringify(d.holdings)){const labels={adjust:'Ændret antal',holdings:'Tilføjet beholdning',move:'Flyttet beholdning',remove:'Fjernet beholdning','edit-holding':'Redigeret beholdning','bulk-holdings':'Masseregistrering'};const difference=d.holdings.reduce((n,h)=>n+h.quantity,0)-holdingsBefore.reduce((n,h)=>n+h.quantity,0);const affectedVersion=d.versions.find(v=>v.id===Number(p.version_id))||d.versions.find(v=>v.id===(holdingsBefore.find(h=>h.id===Number(p.id))?.version_id));const affectedCard=d.cards.find(c=>c.id===affectedVersion?.card_id);const targetLocation=d.locations.find(l=>l.id===Number(p.location_id));const description=labels[route]+(affectedCard?' · '+affectedCard.name+' / '+affectedVersion.name:'')+(targetLocation?' · '+targetLocation.name:'')+(difference?' ('+(difference>0?'+':'')+difference+' eksemplarer)':'');d.auditLog=d.auditLog||[];d.auditLog.push({id:next(d.auditLog),time:new Date().toISOString(),action:route,description,beforeTotal:holdingsBefore.reduce((n,h)=>n+h.quantity,0),afterTotal:d.holdings.reduce((n,h)=>n+h.quantity,0)});d.undoStack=d.undoStack||[];d.undoStack.push({holdings:holdingsBefore,description});d.undoStack=d.undoStack.slice(-20);}await persist(d);return new Response(JSON.stringify(d));
}catch(e){return new Response(JSON.stringify({error:e.name==='QuotaExceededError'?'Browserens lager er fuldt. Tag backup og brug mindre billeder.':e.message}),{status:400});}};
'''
adapter=adapter.replace('__STORAGE__',(base/'storage.js').read_text())
adapter+="\nconst localFetch=window.fetch;let writeQueue=Promise.resolve();window.fetch=(url,opts={})=>{if(!opts.body)return writeQueue.then(()=>localFetch(url,opts));const result=writeQueue.then(()=>localFetch(url,opts));writeQueue=result.catch(()=>{});return result;};\n"
app=app.replace('function parseCSV(text){','function parseCSV(text,separator=\",\"){').replace("c===','&&!quoted","c===separator&&!quoted")
v3="const PKM_CATALOG_GZIP="+repr(base64.b64encode((base/'catalog-ja.json.gz').read_bytes()).decode())+";\n"+(base/'v3.js').read_text()
extraJS=(base/'enhancements.js').read_text()+"\n"+v3+"\n"+(base/'v4.js').read_text()+"\n"+(base/'image-fix.js').read_text()+"\n"+(base/'import-status.js').read_text()+"\n"+(base/'set-code-fix.js').read_text()+"\n"+(base/'v5.js').read_text()+"\n"+(base/'card-details.js').read_text()+"\n"+(base/'ui-v2.js').read_text()+"\n"+(base/'cardmarket.js').read_text()+"\n"+(base/'security.js').read_text()+"\n"+(base/'bundle-links.js').read_text()
extraCSS=(base/'enhancements.css').read_text()+(base/'v3.css').read_text()+(base/'v4.css').read_text()+(base/'v5.css').read_text()+(base/'card-details.css').read_text()+(base/'ui-v2.css').read_text()+(base/'cardmarket.css').read_text()+(base/'security.css').read_text()

extraCSS="@font-face{font-family:'PKM Inter';src:url(data:font/woff2;base64,"+base64.b64encode((base/'inter-latin.woff2').read_bytes()).decode()+") format('woff2');font-weight:100 900;font-style:normal;font-display:swap;}"+extraCSS

backup=r'''
const backupBox=document.createElement('div');backupBox.className='backup';backupBox.innerHTML='<button id="downloadbackup">Gem backup</button> <button id="restorebackup">Indlæs backup</button><input id="backupfile" type="file" accept=".json" hidden><p>Data gemmes i denne browser. Gem backup regelmæssigt. Brug samme fil og browser hver gang.</p>';document.querySelector('main').prepend(backupBox);
document.querySelector('#downloadbackup').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({format:'pkm-backup-v1',data:stored()},null,2)],{type:'application/json'}));a.download='PKM-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
document.querySelector('#restorebackup').onclick=()=>document.querySelector('#backupfile').click();
document.querySelector('#backupfile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const b=JSON.parse(await file.text()),d=b.data;if(b.format!=='pkm-backup-v1'||!d||!['sets','cards','versions','locations','holdings'].every(k=>Array.isArray(d[k])))throw Error('Ugyldig PKM-backup');for(const k of ['sets','cards','versions','locations','holdings']){if(d[k].some(r=>!Number.isSafeInteger(r.id)||r.id<1)||new Set(d[k].map(r=>r.id)).size!==d[k].length)throw Error('Ugyldige ID’er');}
if(d.sets.some(s=>typeof s.name!=='string')||d.locations.some(l=>typeof l.name!=='string')||d.cards.some(c=>typeof c.name!=='string'||typeof c.number!=='string'||typeof c.image!=='string'||!d.sets.some(s=>s.id===c.set_id))||d.versions.some(v=>typeof v.name!=='string'||!d.cards.some(c=>c.id===v.card_id))||d.holdings.some(h=>!Number.isSafeInteger(h.quantity)||h.quantity<1||typeof h.condition!=='string'||!d.versions.some(v=>v.id===h.version_id)||!d.locations.some(l=>l.id===h.location_id)))throw Error('Backup indeholder ugyldige poster');
validateCollectionData(d);if(!confirm('Erstat den nuværende samling med denne backup? Gem først en backup af dine nuværende data.'))return;await persist(d,{backupBeforeReplace:true});db=d;render();alert('Backup indlæst');}catch(err){alert(err.message);}finally{e.target.value='';}};
'''
html=(root/'index.html').read_text().replace('<link rel="stylesheet" href="/style.css">','<style>'+(root/'style.css').read_text()+extraCSS+'.backup{padding-top:15px}.backup p{font-size:11px;margin:8px 0 0}</style>').replace('href="/"','href="#"').replace('Lokal database','Browserlager').replace('<script type="module" src="/app.js"></script>','<script type="module">'+adapter+'\n'+app+'\n'+extraJS+'\n'+backup+'</script>')
script=adapter+'\n'+app+'\n'+extraJS+'\n'+backup
script_hash=base64.b64encode(hashlib.sha256(script.encode()).digest()).decode()
policy="default-src 'none'; script-src 'sha256-"+script_hash+"'; style-src 'unsafe-inline'; font-src data:; img-src data: blob: https: http:; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"
html=html.replace('<head>','<head><meta http-equiv="Content-Security-Policy" content="'+policy+'"><meta name="referrer" content="no-referrer">')
html+='<!-- TCGdex data license\n'+(base/'TCGDEX-LICENSE.txt').read_text()+'\n'+(base/'POKEAPI-LICENSE.txt').read_text()+'\n'+(base/'INTER-LICENSE.txt').read_text()+'\n-->'
release_dir=base.parent/'dist'
release_dir.mkdir(exist_ok=True)
(release_dir/'PKM-UI-V2.2.html').write_text(html)
(release_dir/'PKM-v2.2.3.html').write_text(html)
Path('/tmp/PKM-UI-V2.2.html').write_text(html)
print('Built /tmp/PKM-UI-V2.2.html')
Path('/tmp/pkm-standalone.mjs').write_text(adapter+'\n'+app+'\n'+extraJS+'\n'+backup)
Path('/tmp/pkm-adapter.mjs').write_text(adapter.replace('window.fetch','globalThis.fetch'))
